// Run after assembleHap: exercise the actual ArkUI update callbacks generated by the compiler.
import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
import { stripTypeScriptTypes } from 'node:module';

const source = fs.readFileSync(new URL('../entry/build/default/cache/default/default@CompileArkTS/esmodule/debug/entry/src/main/ets/pages/CloudFiles.ts', import.meta.url), 'utf8');
function method(name) {
  const match = new RegExp(`^    (?:async )?${name}\\(`, 'm').exec(source);
  assert.ok(match, name);
  return source.slice(match.index, source.indexOf('\n    }', match.index) + 6);
}
let text = [], progress = [];
const callbacks = [];
const noop = new Proxy({}, { get: () => () => {} });
const sandbox = vm.createContext({
  Row: noop, Column: noop, Image: noop, If: noop,
  Text: new Proxy({}, { get: (_, name) => name === 'create' ? value => text.push(value) : () => {} }),
  Progress: new Proxy({}, { get: (_, name) => name === 'create' ? value => progress.push(value) : () => {} }),
  AppSpacing: {}, AppFontSize: {}, FontWeight: {}, ImageFit: {}, HorizontalAlign: {}, ProgressType: {},
  ThemeRuntime: noop, MembershipIcons: noop,
  CloudFileClient: { pending: async () => ({ name: '继续上传.epub' }), summary: async () => { throw new Error('rate limited'); } }
});
vm.runInContext(stripTypeScriptTypes(`globalThis.page = {
  ${['usageCard', 'meter', 'formatBytes', 'formatDate', 'refresh'].map(method).join(',\n')}
}`, { mode: 'strip' }), sandbox);
const page = sandbox.page;
page.observeComponentCreation2 = fn => { callbacks.push(fn); fn(0, true); };
page.ifElseBranchUpdateFunction = (_index, fn) => fn();
page.summary = { configured: false, eligible: false, usedBytes: 0, quotaBytes: 1073741824,
  downloadBytes: 0, downloadQuotaBytes: 1073741824, cycleEndsAt: null };
page.summaryLoaded = false;
page.usageCard();
assert.ok(text.includes('暂未获取'));
const initialCallbacks = callbacks.slice();
page.summary = { ...page.summary, configured: true, eligible: true, usedBytes: 40.2 * 1048576,
  downloadBytes: 10 * 1048576, cycleEndsAt: Date.parse('2026-11-01T00:00:00+08:00') };
page.summaryLoaded = true;
text = []; progress = [];
for (const fn of initialCallbacks) fn(0, false);
assert.ok(text.includes('40.2 MB / 1 GB'), text.join('\n'));
assert.ok(text.includes('10.0 MB / 1 GB'));
assert.ok(text.includes('11月1日 00:00 重置（北京时间）'));
assert.deepEqual(progress.map(p => p.value), [40.2 * 1048576, 10 * 1048576]);
page.error = 'upload failed';
await page.refresh(true);
assert.equal(page.pendingName, '继续上传.epub', 'failed summary must not hide the resumable task');
assert.equal(page.error, 'upload failed', 'refresh must not replace the actual transfer error');
await page.refresh();
assert.equal(page.error, 'rate limited');
console.log('PASS compiled cloud UI: async storage/traffic updates, reset date and resumable task after failed refresh');
